String dtext(dynamic v){final d=DateTime.tryParse('$v');return d==null?'$v':DateFormat('yyyy/MM/dd').format(d);}

class DB{static Database? _d;static Future<Database> get d async{if(_d!=null)return _d!;final f=p.join(await getDatabasesPath(),'smart_assistant.db');return _d=await openDatabase(f,version:1,onCreate:(db,v)async{await db.execute('CREATE TABLE customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,notes TEXT,created TEXT)');await db.execute('CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT,qty REAL,minimum REAL,price REAL,created TEXT)');await db.execute('CREATE TABLE dues(id INTEGER PRIMARY KEY AUTOINCREMENT,customer TEXT,amount REAL,due TEXT,note TEXT,status TEXT)');await db.execute('CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,customer TEXT,type TEXT,amount REAL,note TEXT,date TEXT)');});}}

class AppState extends ChangeNotifier{void setTab(int i){tab=i;notifyListeners();}int tab=0;Map<String,dynamic> st={};List<Map<String,dynamic>> customers=[],products=[],dues=[];String key='',model='openai/gpt-oss-20b:free',base='https://openrouter.ai/api/v1/chat/completions';Future<void> init()async{final q=await SharedPreferences.getInstance();key=q.getString('key')??'';model=q.getString('model')??model;base=q.getString('base')??base;await refresh();}Future<void> refresh()async{final db=await DB.d;customers=await db.query('customers',orderBy:'name');products=await db.query('products',orderBy:'name');dues=await db.query('dues',orderBy:'due');final c=(await db.rawQuery('SELECT COUNT(*) n FROM customers')).first['n'] as int;final pr=(await db.rawQuery('SELECT COUNT(*) n FROM products')).first['n'] as int;final low=(await db.rawQuery('SELECT COUNT(*) n FROM products WHERE qty<=minimum')).first['n'] as int;final du=(await db.rawQuery('SELECT COUNT(*) n FROM dues WHERE status="pending"')).first['n'] as int;final owed=(await db.rawQuery('SELECT COALESCE(SUM(amount),0) n FROM transactions WHERE type="debt"')).first['n'] as num;final paid=(await db.rawQuery('SELECT COALESCE(SUM(amount),0) n FROM transactions WHERE type="payment"')).first['n'] as num;st={'customers':c,'products':pr,'low':low,'dues':du,'owed':owed.toDouble(),'paid':paid.toDouble()};notifyListeners();}Future<void> saveAI(String k,String m,String b)async{final q=await SharedPreferences.getInstance();await q.setString('key',k);await q.setString('model',m);await q.setString('base',b);key=k;model=m;base=b;notifyListeners();}}

Future<void> editor(BuildContext c,String title,List<Map<String,dynamic>> fs,Future<void> Function(Map<String,String>) save)async{final cs={for(final f in fs)f['k'] as String:TextEditingController(text:'${f['v']??''}')};await showDialog(context:c,builder:(x)=>AlertDialog(backgroundColor:card,title:Text(title),content:SingleChildScrollView(child:Column(children:[for(final f in fs)Padding(padding:const EdgeInsets.only(bottom:9),child:TextField(controller:cs[f['k']],keyboardType:f['num']==true?TextInputType.number:TextInputType.text,decoration:InputDecoration(labelText:f['l'] as String)))])),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('إلغاء')),FilledButton(onPressed:()async{await save({for(final e in cs.entries)e.key:e.value.text});if(x.mounted)Navigator.pop(x);},child:const Text('حفظ'))]));for(final x in cs.values)x.dispose();}

