class Donut extends CustomPainter{final double a,b;Donut(this.a,this.b);@override void paint(Canvas x,Size s){final p=Paint()..style=PaintingStyle.stroke..strokeWidth=18;final r=Rect.fromCircle(center:s.center(Offset.zero),radius:s.width*.34),t=a+b;final aa=t==0?0:2*math.pi*b/t;p.color=green;x.drawArc(r,-math.pi/2,aa,false,p);p.color=red;x.drawArc(r,-math.pi/2+aa,t==0?0:2*math.pi*a/t,false,p);}@override bool shouldRepaint(covariant Donut o)=>o.a!=a||o.b!=b;}
