class _IP extends State<ImportPage>{String msg='اختر CSV أو XLSX ثم اختر نوع البيانات.';bool busy=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('الاستيراد الذكي')),body:ListView(padding:const EdgeInsets.all(16),children:[FilledButton.icon(onPressed:busy?null:()=>pick(c,'customers'),icon:const Icon(Icons.people),label:const Text('استيراد العملاء')),FilledButton.icon(onPressed:busy?null:()=>pick(c,'products'),icon:const Icon(Icons.inventory_2),label:const Text('استيراد الأصناف')),const SizedBox(height:15),Card(color:card,child:Padding(padding:const EdgeInsets.all(15),child:Text(msg))),const SizedBox(height:10),const Text('صيغة العملاء: name,phone,notes\nصيغة الأصناف: name,category,qty,minimum,price',style:TextStyle(color:muted))]));Future<void>pick(BuildContext c,String type)async{setState(()=>busy=true);try{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['csv','xlsx']);if(r==null||r.files.single.path==null)return;final f=File(r.files.single.path!),name=r.files.single.name;final d=await DB.d;if(name.toLowerCase().endsWith('.csv')){final rows=const CsvToListConverter().convert(await f.readAsString());for(final row in rows.skip(1)){String z(int i)=>i<row.length?'${row[i]}':'';if(type=='customers')await d.insert('customers',{'name':z(0),'phone':z(1),'notes':z(2),'created':DateTime.now().toIso8601String()});else await d.insert('products',{'name':z(0),'category':z(1),'qty':double.tryParse(z(2))??0,'minimum':double.tryParse(z(3))??0,'price':double.tryParse(z(4))??0,'created':DateTime.now().toIso8601String()});}}else{final book=excel.Excel.decodeBytes(await f.readAsBytes());for(final sh in book.tables.values){for(final row in sh.rows.skip(1)){String z(int i)=>i<row.length?'${row[i]?.value??''}':'';if(type=='customers')await d.insert('customers',{'name':z(0),'phone':z(1),'notes':z(2),'created':DateTime.now().toIso8601String()});else await d.insert('products',{'name':z(0),'category':z(1),'qty':double.tryParse(z(2))??0,'minimum':double.tryParse(z(3))??0,'price':double.tryParse(z(4))??0,'created':DateTime.now().toIso8601String()});}}}await c.read<AppState>().refresh();setState(()=>msg='تم استيراد $name بنجاح.');}catch(e){setState(()=>msg='فشل الاستيراد: $e');}finally{if(mounted)setState(()=>busy=false);}}}

