class _Chat extends State<Chat>{final q=TextEditingController();final ms=<Map<String,String>>[{'r':'a','t':'مرحباً بك في المساعد الذكي. اسألني عن العملاء أو الأصناف أو الاستحقاقات.'}];bool busy=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('المساعد الذكي')),body:Column(children:[Expanded(child:ListView.builder(padding:const EdgeInsets.all(14),itemCount:ms.length,itemBuilder:(c,i)=>Align(alignment:ms[i]['r']=='u'?Alignment.centerLeft:Alignment.centerRight,child:Container(margin:const EdgeInsets.only(bottom:8),padding:const EdgeInsets.all(12),constraints:const BoxConstraints(maxWidth:340),decoration:BoxDecoration(color:ms[i]['r']=='u'?blue:card,borderRadius:BorderRadius.circular(16)),child:Text(ms[i]['t']!))))),Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:q,decoration:const InputDecoration(hintText:'اكتب سؤالك...'))),IconButton.filled(onPressed:busy?null:send,icon:const Icon(Icons.send))]))]));Future<void>send()async{final text=q.text.trim();if(text.isEmpty)return;setState((){ms.add({'r':'u','t':text});q.clear();busy=true;});final s=context.read<AppState>();try{if(s.key.isEmpty){ms.add({'r':'a','t':'أضف API Key من الإعدادات لتفعيل الذكاء الاصطناعي.'});return;}final data=jsonEncode(s.st);final r=await http.post(Uri.parse(s.base),headers:{'Authorization':'Bearer ${s.key}','Content-Type':'application/json'},body:jsonEncode({'model':s.model,'messages':[{'role':'system','content':'أنت مساعد إدارة عربي. لا تخترع بيانات. إحصاءات التطبيق: $data'},{'role':'user','content':text}]}));if(r.statusCode>=200&&r.statusCode<300){final j=jsonDecode(r.body);ms.add({'r':'a','t':'${j['choices'][0]['message']['content']??'لا توجد إجابة'}'});}else{ms.add({'r':'a','t':'فشل الاتصال (${r.statusCode}).'});}}catch(e){ms.add({'r':'a','t':'خطأ اتصال: $e'});}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){q.dispose();super.dispose();}}

